const std=@import("std");const K=@import("experimental/soil_root_kernel_v2.zig");
fn total(s:K.State)f128{var t=@as(f128,s.surface)+s.soil+s.vapor;for(s.cohorts)|c|t+=c.water;return t;}
fn plant(root:f64,storage:f64,water:f64)K.Cohort{return .{.biomass=1,.support=1,.root_fraction=root,.storage_fraction=storage,.water=water};}
test "root-only paid throughput and storage-only delivery share one demand"{var s=K.State{.soil=1};s.cohorts[0]=plant(0.25,0,0);const p=K.Params{.dt=1,.capacity=1,.conductance=1,.demand=.{0.125,0,0,0},.exposure=.{1,0,0,0}};const r=K.step(s,p).?;try std.testing.expectEqual(@as(f64,0.125),r.root_receipts[0]);try std.testing.expectEqual(@as(f64,0),r.store_receipts[0]);try std.testing.expectEqual(@as(f64,1),r.h_paid[0]);try std.testing.expectEqual(total(s),total(r.state));s.cohorts[0]=plant(0,0.25,0.25);const storage=K.step(s,p).?;try std.testing.expectEqual(@as(f64,0.125),storage.store_receipts[0]);s.cohorts[0]=plant(0.25,0.25,0.25);const both=K.step(s,p).?;try std.testing.expectEqual(@as(f64,0),both.store_receipts[0]);try std.testing.expectEqual(@as(f64,0.5),both.canopy_carbon[0]);try std.testing.expectEqual(total(s),total(both.state));}
test "finite abiotic transfers no organism RNG and zero full controls"{const s=K.State{.surface=4};const p=K.Params{.dt=2,.capacity=1,.infiltration_rate=1,.evaporation_rate=0.125,.drainage_rate=0.125};const r=K.step(s,p).?;try std.testing.expectEqual(@as(f64,1),r.infiltrated);try std.testing.expectEqual(@as(f64,0.25),r.evaporated);try std.testing.expectEqual(@as(f64,0.25),r.drained);try std.testing.expectEqual(total(s),total(r.state));try std.testing.expectEqualDeep(K.State{},K.step(.{},.{.dt=1,.capacity=0}).?.state);}
test "all24 unequal slot permutations"{var s=K.State{.soil=0.125};s.cohorts=.{plant(0.125,0,0),plant(0.25,0,0),plant(0.375,0,0),plant(0.25,0,0)};const p=K.Params{.dt=1,.capacity=0.25,.conductance=1,.demand=.{1,1,1,1},.exposure=.{1,1,1,1}};const ref=K.step(s,p).?;var n:usize=0;for(0..4)|a|for(0..4)|b|for(0..4)|c|for(0..4)|d|{if(a==b or a==c or a==d or b==c or b==d or c==d)continue;var x=s;const order=[_]usize{a,b,c,d};for(order,0..)|j,i|x.cohorts[i]=s.cohorts[j];const r=K.step(x,p).?;for(order,0..)|j,i|try std.testing.expectEqual(ref.root_receipts[j],r.root_receipts[i]);try std.testing.expectEqual(ref.state.soil,r.state.soil);try std.testing.expectEqual(total(x),total(r.state));n+=1;};try std.testing.expectEqual(@as(usize,24),n);}
test "zero demand exposure temperature and depth spend no physiological water"{var s=K.State{.soil=1};s.cohorts[0]=plant(0.25,0.25,0.25);var p=K.Params{.dt=1,.capacity=1,.conductance=1};try std.testing.expectEqualDeep(s,K.step(s,p).?.state);p.demand[0]=1;try std.testing.expectEqualDeep(s,K.step(s,p).?.state);p.exposure[0]=1;p.temperature=273.15;try std.testing.expectEqualDeep(s,K.step(s,p).?.state);p.temperature=300;p.depth_m=0.2;try std.testing.expectEqualDeep(s,K.step(s,p).?.state);}
test "invalid and unrepresentable transfer refuses unchanged"{var s=K.State{.soil=1,.vapor=1e100};s.cohorts[0]=plant(0.25,0,0);const p=K.Params{.dt=1,.capacity=1,.conductance=1,.demand=.{0.125,0,0,0},.exposure=.{1,0,0,0}};try std.testing.expectEqualDeep(s,K.step(s,p).?.state);var invalid=p;invalid.dt=0;try std.testing.expect(K.step(s,invalid)==null);invalid=p;invalid.capacity=std.math.nan(f64);try std.testing.expect(K.step(s,invalid)==null);s.vapor=0;s.cohorts[0].storage_fraction=1;try std.testing.expect(K.step(s,p)==null);}
test "fixed natural supported carbon root-only prescribed allocation"{var s=K.State{.soil=1};s.cohorts[0]=.{.biomass=0.12940502166748047,.support=0.017374489456415176,.root_fraction=0.25};const r=K.step(s,.{.dt=1,.capacity=1,.conductance=1,.demand=.{0.125,0,0,0},.exposure=.{1,0,0,0}}).?;try std.testing.expect(r.root_receipts[0]>0 and r.store_receipts[0]==0);try std.testing.expectEqual(total(s),total(r.state));std.debug.print("ROOT_REFERENCE paid_root_C={d} flow={d} h_paid={d} assigned_allocation_not_evolved=true\n",.{r.root_carbon[0],r.root_receipts[0],r.h_paid[0]});}
test "closed finite wetting evaporation uptake drainage cycles exhaust without refill"{var s=K.State{.surface=1};s.cohorts[0]=plant(0.25,0,0);const initial=total(s);const p=K.Params{.dt=1,.capacity=0.25,.infiltration_rate=0.125,.evaporation_rate=0.03125,.drainage_rate=0.0625,.conductance=1,.demand=.{0.03125,0,0,0},.exposure=.{1,0,0,0}};var delivered:f64=0;for(0..1000)|_|{const r=K.step(s,p).?;delivered+=r.root_receipts[0];s=r.state;try std.testing.expectEqual(initial,total(s));}try std.testing.expectEqual(@as(f64,0),s.surface);try std.testing.expectEqual(@as(f64,0),s.soil);try std.testing.expectEqual(@as(f64,1),s.vapor);try std.testing.expect(delivered>0 and delivered<1);std.debug.print("CLOSED1000 root_delivered={d} remaining_surface={d} soil={d} vapor={d}\n",.{delivered,s.surface,s.soil,s.vapor});}
test "storage drought exhausts and no root or zero demand subsidy"{var s=K.State{};s.cohorts[0]=plant(0,0.25,0.5);const p=K.Params{.dt=1,.capacity=1,.conductance=1,.demand=.{0.125,0,0,0},.exposure=.{1,0,0,0}};for(0..20)|i|{const r=K.step(s,p).?;try std.testing.expectEqual(@as(f64,if(i<4)1 else 0),r.h_paid[0]);try std.testing.expectEqual(total(s),total(r.state));s=r.state;}try std.testing.expectEqual(@as(f64,0.5),s.vapor);}
test "fixed declining substrate reports representability refusal rather than topup"{var s=K.State{.soil=1};s.cohorts[0]=plant(0.25,0,0);const p=K.Params{.dt=1,.capacity=1,.conductance=1,.demand=.{1,0,0,0},.exposure=.{1,0,0,0}};var accepted:usize=0;var refused=false;for(0..1000)|_|{if(K.step(s,p))|r|{try std.testing.expectEqual(total(s),total(r.state));s=r.state;accepted+=1;}else{refused=true;break;}}std.debug.print("DECLINING1000 accepted={d} refusal={} remaining_soil={d} vapor={d}\n",.{accepted,refused,s.soil,s.vapor});try std.testing.expect(accepted>0);}
test "inactive huge store cannot block active exact storage transfer"{const B=@import("experimental/bounded_water.zig");const r=B.gather(.{1,1e100,0,0},0,.{1,0,0,0});try std.testing.expectEqual(@as(f64,1),r.paid[0]);try std.testing.expectEqual(@as(f64,1e100),r.sources[1]);try std.testing.expectEqual(@as(f64,1),r.target);}
test "receiver quantum skip does not stop independent drainage"{const s=K.State{.soil=1,.vapor=1e100};const r=K.step(s,.{.dt=1,.capacity=1,.evaporation_rate=0.125,.drainage_rate=0.25}).?;try std.testing.expectEqual(@as(f64,0),r.evaporated);try std.testing.expectEqual(@as(f64,0.25),r.drained);try std.testing.expectEqual(@as(f64,0.75),r.state.soil);}
test "step27 uses represented receiver amount and leaves unspent source"{const B=@import("experimental/bounded_water.zig");const source:f64=0.0005644075936237503;const target:f64=0.9994355924063762;const wanted:f64=0.00014110189840593756;const r=B.scatter(source,target,.{wanted,0,0,0});try std.testing.expectEqual(@as(f64,0.00014110189840588205),r.paid[0]);try std.testing.expectEqual(@as(f64,0.0004233056952178682),r.source);try std.testing.expectEqual(@as(f128,source)-r.source,@as(f128,r.target)-target);try std.testing.expect(r.paid[0]<wanted);}
